    additive := multiplicative (('+' | '-') multiplicative)*
    multiplicative := power (('*' | '/' | '//' | '%') power)*
    power  := ('**' power)?  unary_rhs     # right-assoc; '**' binds tighter than unary
    unary  := ('+' | '-')* primary
    primary := number | funcall | '(' expr ')'
"""


class _Lexer:
    def __init__(self, text):
        self.text = text
        self.pos = 0
        self.n = len(text)

    def error(self, msg):
        raise ValueError(msg)

    def skip_ws(self):
        while self.pos < self.n and self.text[self.pos].isspace():
            self.pos += 1

    def peek(self):
        self.skip_ws()
        if self.pos >= self.n:
            return None
        return self.text[self.pos]

    def next_token(self):
        self.skip_ws()
        if self.pos >= self.n:
            return None, None
        c = self.text[self.pos]
        # numbers
        if c.isdigit() or c == '.':
            start = self.pos
            if c == '.':
                self.pos += 1
                while self.pos < self.n and self.text[self.pos].isdigit():
                    self.pos += 1
                return 'num', float(self.text[start:self.pos])
            while self.pos < self.n and self.text[self.pos].isdigit():
                self.pos += 1
            value = int(self.text[start:self.pos])
            if self.pos < self.n and self.text[self.pos] == '.':
                # a following dot must start a decimal, not be malformed like '1..2'
                self.pos += 1
                while self.pos < self.n and self.text[self.pos].isdigit():
                    self.pos += 1
                value = float(self.text[start:self.pos])
            return 'num', value
        # names
